  `browser` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '浏览器',
  `cost_time` bigint(10) NULL DEFAULT NULL COMMENT '耗费时间',
  PRIMARY KEY (`oper_id`) USING BTREE
